fun reachableFrom(root: Int, calls: Map<Int, Set<Int>>): Set<Int> {
    val seen = mutableSetOf<Int>()
    val pending = mutableListOf(root)
    while (pending.isNotEmpty()) {
        val id = pending.removeAt(pending.lastIndex)
        if (seen.add(id)) pending.addAll(calls[id].orEmpty().sorted())
    }
    return seen
}
fun warningLines(program: Program, semantic: Semantic, reachable: Set<Int>): List<String> {
    val warnings = mutableListOf<Pair<Position, String>>()
    for (symbol in semantic.symbols) {
        if (symbol.variable != null && symbol.reads == 0) warnings.add(Pair(symbol.name.position, "unused ${if (symbol.parameter) "parameter" else "variable"} '${symbol.name.text}'"))
        if (symbol.function != null && symbol.function.id !in reachable) warnings.add(Pair(symbol.name.position, "function '${symbol.name.text}' is never called"))
    }
    fun walk(statement: Stmt) {
        when (val s = statement.kind) {
            is StmtKind.Block -> {
                val i = s.statements.indexOfFirst {
                    !canComplete(it)
                }
                if (i >= 0 && i + 1 < s.statements.size) warnings.add(Pair(s.statements[i + 1].position, "unreachable statement"))
                s.statements.forEach {
                    walk(it)
                }
            }
            is StmtKind.Conditional -> {
                walk(s.yes)
                s.no?.let {
                    walk(it)
                }
            }
            is StmtKind.WhileLoop -> walk(s.body)
            is StmtKind.ForLoop -> {
                s.initial?.let {
                    walk(it)
                }
                s.update?.let {
                    walk(it)
                }
                walk(s.body)
            }
            else -> Unit
        }
    }
    for (declaration in program.declarations) if (declaration is Top.FunctionDecl) walk(declaration.function.body)
    return warnings.sortedBy {
        it.first
    }.map {
        "warning ${it.first}: ${it.second}"
    }
}
class Folder {
    var count = 0
    fun literal(expression: Expr): Long? = when (val e = expression.kind) {
        is ExprKind.Integer -> e.value
        is ExprKind.BooleanValue -> if (e.value) 1L else 0L
        else -> null
    }
    fun boolean(expression: Expr, value: Boolean): Boolean = (expression.kind as? ExprKind.BooleanValue)?.value == value
    fun integer(expression: Expr, value: Long): Boolean = (expression.kind as? ExprKind.Integer)?.value == value
    fun made(old: Expr, value: Long, type: ToyType): Expr {
        val result = Expr(old.position, if (type == ToyType.BOOL) ExprKind.BooleanValue(value != 0L) else ExprKind.Integer(value))
        result.type = type
        count++
        return result
    }
    fun expression(original: Expr): Expr {
        when (val e = original.kind) {
            is ExprKind.Element -> original.kind = e.copy(index = expression(e.index))
            is ExprKind.Call -> original.kind = e.copy(arguments = e.arguments.map {
                expression(it)
            })
            is ExprKind.Unary -> {
                val value = expression(e.value)
                original.kind = e.copy(value = value)
                val v = literal(value)
                if (v != null) {
                    val result = if (e.op == "!") {
                        if (v == 0L) 1L else 0L
                    } else -v
                    if (result in -2147483648L..2147483647L) return made(original, result, original.type!!)
                }
            }
            is ExprKind.Binary -> {
                val a = expression(e.left)
                val b = expression(e.right)
                original.kind = e.copy(left = a, right = b)
                val x = literal(a)
                val y = literal(b)
                if (x != null && y != null) {
                    val value: Long? = when (e.op) {
                        "+" -> x + y
                        "-" -> x - y
                        "*" -> x * y
                        "/" -> if (y != 0L) x / y else null
                        "%" -> if (y != 0L) x - y * (x / y) else null
                        "<" -> if (x < y) 1L else 0L
                        "<=" -> if (x <= y) 1L else 0L
                        ">" -> if (x > y) 1L else 0L
                        ">=" -> if (x >= y) 1L else 0L
                        "==" -> if (x == y) 1L else 0L
                        "!=" -> if (x != y) 1L else 0L
                        "&&" -> if (x != 0L && y != 0L) 1L else 0L
                        "||" -> if (x != 0L || y != 0L) 1L else 0L
                        else -> null
                    }
                    if (value != null && value in -2147483648L..2147483647L) return made(original, value, original.type!!)
                }
                if (e.op == "&&" && boolean(a, false)) return made(original, 0, ToyType.BOOL)
                if (e.op == "||" && boolean(a, true)) return made(original, 1, ToyType.BOOL)
                if (e.op == "&&" && boolean(a, true) || e.op == "||" && boolean(a, false) || e.op == "+" && integer(a, 0) || e.op == "*" && integer(a, 1)) {
                    count++
                    return b
                }
                if (e.op in listOf("+", "-") && integer(b, 0) || e.op in listOf("*", "/") && integer(b, 1) || e.op == "&&" && boolean(b, true) || e.op == "||" && boolean(b, false)) {
                    count++
                    return a
                }
            }
            else -> Unit
        }
        return original
    }
    fun statement(original: Stmt): Stmt {
        when (val s = original.kind) {
            is StmtKind.Block -> original.kind = s.copy(statements = s.statements.map {
                statement(it)
            })
            is StmtKind.Declaration -> s.variable.initializer = s.variable.initializer?.let {
                expression(it)
            }
            is StmtKind.Assignment -> original.kind = s.copy(index = s.index?.let {
                expression(it)
            }, value = expression(s.value))
            is StmtKind.Call -> original.kind = s.copy(value = expression(s.value))
            is StmtKind.Print -> original.kind = s.copy(values = s.values.map {
                expression(it)
            })
            is StmtKind.ReturnValue -> original.kind = s.copy(value = s.value?.let {
                expression(it)
            })
            is StmtKind.Conditional -> {
                val condition = expression(s.condition)
                val kind = condition.kind
                if (kind is ExprKind.BooleanValue) {
                    count++
                    return if (kind.value) statement(s.yes) else s.no?.let {
                        statement(it)
                    } ?: Stmt(original.position, StmtKind.Empty)
                }
                original.kind = s.copy(condition = condition, yes = statement(s.yes), no = s.no?.let {
                    statement(it)
                })
            }
            is StmtKind.WhileLoop -> {
                val condition = expression(s.condition)
                if (boolean(condition, false)) {
                    count++
                    return Stmt(original.position, StmtKind.Empty)
                }
                original.kind = s.copy(condition = condition, body = statement(s.body))
            }
            is StmtKind.ForLoop -> original.kind = s.copy(initial = s.initial?.let {
                statement(it)
            }, condition = s.condition?.let {
                expression(it)
            }, update = s.update?.let {
                statement(it)
            }, body = statement(s.body))
            else -> Unit
        }
        return original
    }
    fun program(program: Program, reachable: Set<Int>) {
        for (declaration in program.declarations) {
            when (declaration) {
                is Top.VariableDecl -> declaration.variable.initializer = declaration.variable.initializer?.let {
                    expression(it)
                }
                is Top.FunctionDecl -> if (declaration.function.id in reachable) statement(declaration.function.body)
            }
        }
    }
}
val ruleNames = listOf("const-jump", "not-compare", "not-jump", "invert-branch", "thread", "jump-next", "unreachable")
fun isJump(op: String): Boolean = op in listOf("JUMP", "JUMPF", "JUMPT")
fun conditional(op: String): Boolean = op in listOf("JUMPF", "JUMPT")
fun transfer(op: String): Boolean = op in listOf("JUMP", "RET", "RETV", "HALT")
fun jumps(op: String, value: Long): Boolean = if (op == "JUMPF") value == 0L else value != 0L
fun inverse(op: String): String = if (op == "JUMPF") "JUMPT" else "JUMPF"
fun peephole(original: List<Instruction>): Pair<List<Instruction>, IntArray> {
    val code = original.map {
        it.snapshot()
    }.toMutableList()
    val counts = IntArray(7)
    fun delete(index: Int) {
        code.removeAt(index)
        for (instruction in code) if (isJump(instruction.op) && instruction.operands[0] > index.toLong()) instruction.operands[0]--
    }
    while (true) {
        val targets = code.filter {
            isJump(it.op)
        }.map {
            it.operands[0].toInt()
        }.toSet()
        var changed = false
        for (i in code.indices) {
            val a = code[i]
            val b = code.getOrNull(i + 1)
            val free = b != null && i + 1 !in targets
            if (b != null && free && a.op == "PUSH" && conditional(b.op)) {
                if (jumps(b.op, a.operands[0])) {
                    code[i] = Instruction("JUMP", b.operands.toMutableList(), b.position)
                    delete(i + 1)
                } else {
                    delete(i + 1)
                    delete(i)
                }
                counts[0]++
            }
            else if (b != null && free && b.op == "NOT" && a.op in listOf("LT", "LE", "GT", "GE", "EQ", "NE")) {
                a.op = mapOf("LT" to "GE", "LE" to "GT", "GT" to "LE", "GE" to "LT", "EQ" to "NE", "NE" to "EQ").getValue(a.op)
                delete(i + 1)
                counts[1]++
            }
            else if (b != null && free && a.op == "NOT" && conditional(b.op)) {
                code[i] = Instruction(inverse(b.op), b.operands.toMutableList(), b.position)
                delete(i + 1)
                counts[2]++
            }
            else if (b != null && free && conditional(a.op) && a.operands[0] == (i + 2).toLong() && b.op == "JUMP") {
                code[i] = Instruction(inverse(a.op), b.operands.toMutableList(), a.position)
                delete(i + 1)
                counts[3]++
            }
            else {
                var target: Long? = null
                if (isJump(a.op) && a.operands[0] < code.size.toLong()) {
                    val t = a.operands[0].toInt()
                    val at = code[t]
                    if (at.op == "JUMP") target = at.operands[0] else if (at.op == "PUSH" && t + 1 < code.size && conditional(code[t + 1].op)) target = if (jumps(code[t + 1].op, at.operands[0])) code[t + 1].operands[0] else (t + 2).toLong()
                }
                if (target != null && target != a.operands[0]) {
                    a.operands[0] = target
                    counts[4]++
                }
                else if (isJump(a.op) && a.operands[0] == (i + 1).toLong()) {
                    if (a.op == "JUMP") delete(i) else code[i] = Instruction("POP", mutableListOf(), a.position)
                    counts[5]++
                }
                else if (free && transfer(a.op)) {
                    delete(i + 1)
                    counts[6]++
                } else continue
            }
            changed = true
            break
        }
        if (!changed) return Pair(code, counts)
    }
}
fun successors(code: List<Instruction>, index: Int): List<Int> {
    val instruction = code[index]
    val result = mutableListOf<Int>()
    if (!transfer(instruction.op) && index + 1 < code.size) result.add(index + 1)
    if (isJump(instruction.op) && instruction.operands[0] < code.size.toLong() && instruction.operands[0].toInt() !in result) result.add(instruction.operands[0].toInt())
    return result
}
data class BasicBlock(val first: Int, val last: Int, val successors: List<Int>)
fun blocks(code: List<Instruction>): List<BasicBlock> {
    val leaders = mutableSetOf(0)
    for ((i, instruction) in code.withIndex()) {
        if (isJump(instruction.op) && instruction.operands[0] < code.size.toLong()) leaders.add(instruction.operands[0].toInt())
        if ((isJump(instruction.op) || transfer(instruction.op)) && i + 1 < code.size) leaders.add(i + 1)
    }
    val sorted = leaders.sorted()
    val index = sorted.withIndex().associate {
        it.value to it.index
    }
    return sorted.mapIndexed {
        k, first -> val last = if (k + 1 < sorted.size) sorted[k + 1] - 1 else code.lastIndex
        BasicBlock(first, last, successors(code, last).map {
            index.getValue(it)
        })
    }
}
fun stackDepth(code: List<Instruction>, semantic: Semantic): Int {
    fun effect(instruction: Instruction): Int = when (instruction.op) {
        "PUSH", "LOADG", "LOADL", "READ" -> 1
        "POP", "STOREG", "STOREL", "JUMPF", "JUMPT", "RETV", "ADD", "SUB", "MUL", "DIV", "MOD", "LT", "LE", "GT", "GE", "EQ", "NE" -> -1
        "STOREA" -> -2
        "CALL" -> -instruction.operands[1].toInt() + if (semantic.symbols[instruction.callee!!].type == ToyType.VOID) 0 else 1
        "PRINT" -> -instruction.operands[0].toInt()
        else -> 0
    }
    val depth = mutableMapOf(0 to 0)
    val pending = mutableListOf(0)
    var maximum = 0
    while (pending.isNotEmpty()) {
        val i = pending.removeAt(pending.lastIndex)
        val next = depth.getValue(i) + effect(code[i])
        maximum = maxOf(maximum, next)
        for (j in successors(code, i)) if (j !in depth) {
            depth[j] = next
            pending.add(j)
        }
    }
    return maximum
}
data class FlatCode(val instructions: List<Instruction>, val owners: List<Int>, val starts: List<Int>)
fun flatten(units: List<CodeUnit>): FlatCode {
    val starts = mutableListOf<Int>()
    val functionStarts = mutableMapOf<Int, Int>()
    var address = 0
    for (unit in units) {
        starts.add(address)
        unit.function?.let {
            functionStarts[it.id] = address
        }
        address += unit.code.size
    }
    val instructions = mutableListOf<Instruction>()
    val owners = mutableListOf<Int>()
    for ((i, unit) in units.withIndex()) for (original in unit.code) {
        val instruction = original.snapshot()
        if (isJump(instruction.op)) instruction.operands[0] += starts[i].toLong()
        if (instruction.op == "CALL") instruction.operands[0] = functionStarts.getValue(instruction.callee!!).toLong()
        instructions.add(instruction)
        owners.add(i)
    }
    return FlatCode(instructions, owners, starts)
}
fun spelling(instruction: Instruction): String = instruction.op + instruction.operands.joinToString("") {
    " $it"
}
fun pad(text: String, width: Int, left: Boolean = false): String = if (left) text.padEnd(width) else text.padStart(width)
fun listingLines(program: Program, semantic: Semantic, before: List<CodeUnit>, after: List<CodeUnit>, old: FlatCode, new: FlatCode): List<String> {
    val globals = program.declarations.filterIsInstance<Top.VariableDecl>().map {
        it.variable
    }
    val lines = mutableListOf(if (globals.isEmpty()) "globals: none" else "globals:")
    for (variable in globals) lines.add("  ${variable.address} ${variable.name.text} " + (variable.size?.let {
        "int[$it]"
    } ?: variable.type.text))
    lines.add("functions:")
    for ((i, unit) in after.withIndex()) {
        val function = unit.function
        val signature = function?.let {
            " ${it.type.text}(${it.parameters.joinToString(",") { p -> p.type.text }})"
        } ?: ""
        val callees = function?.let {
            semantic.calls[it.id].orEmpty().map {
                id -> semantic.symbols[id].name.text
            }.sorted()
        } ?: listOf("main")
        val recursive = function?.let {
            f -> semantic.calls[f.id].orEmpty().any {
                f.id in reachableFrom(it, semantic.calls)
            }
        } ?: false
        lines.add("  ${unit.name}$signature address=${old.starts[i]}->${new.starts[i]} size=${before[i].code.size}->${unit.code.size} slots=${unit.slots.size} stack=${stackDepth(unit.code, semantic)} blocks=${blocks(unit.code).size} calls=${if (callees.isEmpty()) "-" else callees.joinToString(",")}" + if (recursive) " recursive" else "")
        for ((slot, variable) in unit.slots.withIndex()) lines.add("    slot $slot ${variable.name.text} ${variable.type.text}")
    }
    lines.add("references:")
    val referents = globals.map {
        it.id
    } + program.declarations.filterIsInstance<Top.FunctionDecl>().map {
        it.function.id
    }
    for (id in referents) {
        val symbol = semantic.symbols[id]
        val uses = symbol.references.map {
            it.line
        }.distinct().sorted()
        lines.add("  ${symbol.name.text} defined ${symbol.name.position.line} used ${if (uses.isEmpty()) "-" else uses.joinToString(" ")}")
    }
    for ((heading, units, flat) in listOf(Triple("before", before, old), Triple("after", after, new))) {
        lines.add("$heading peephole: ${flat.instructions.size} instructions")
        for ((i, unit) in units.withIndex()) {
            lines.add(unit.name + ":")
            for (j in unit.code.indices) {
                val pc = flat.starts[i] + j
                lines.add(pad(pc.toString(), 5) + "  " + spelling(flat.instructions[pc]))
            }
        }
    }
    lines.add("control flow:")
    for ((i, unit) in after.withIndex()) {
        lines.add("  " + unit.name)
        for ((k, block) in blocks(unit.code).withIndex()) lines.add("    B$k ${new.starts[i] + block.first}-${new.starts[i] + block.last}" + if (block.successors.isEmpty()) "" else " -> " + block.successors.joinToString(" ") {
            "B$it"
        })
    }
    return lines
}
fun statsLines(beforeCount: Int, after: List<CodeUnit>, code: FlatCode, main: VMResult, comparison: VMResult, folds: Int, rules: IntArray): List<String> {
    val lines = mutableListOf("code: $beforeCount -> ${code.instructions.size}", "folds: $folds", "peephole: ${rules.sum()}")
    for (i in ruleNames.indices) lines.add("  ${ruleNames[i]} ${rules[i]}")
    lines.addAll(listOf("executed: ${main.executed}", "executed before peephole: ${comparison.executed}", "behaviour: ${if (main.output == comparison.output && main.message == comparison.message) "same" else "different"}", "max call depth: ${main.maxDepth}", "max stack: ${main.maxStack}", "opcodes:"))
    val opcodes = mutableMapOf<String, Int>()
    val unitCounts = IntArray(after.size)
    val lineCounts = mutableMapOf<Int, Int>()
    for ((pc, instruction) in code.instructions.withIndex()) {
        val count = main.counts[pc]
        opcodes[instruction.op] = (opcodes[instruction.op] ?: 0) + count
        unitCounts[code.owners[pc]] += count
        lineCounts[instruction.position.line] = (lineCounts[instruction.position.line] ?: 0) + count
    }
    for ((op, count) in opcodes.entries.filter {
        it.value > 0
    }.sortedWith(compareByDescending<Map.Entry<String, Int>> {
        it.value
    }.thenBy {
        it.key
    })) lines.add("  $op $count")
    lines.add("functions:")
    for (i in after.indices.drop(1).sortedWith(compareByDescending<Int> {
        unitCounts[it]
    }.thenBy {
        after[it].name
    })) lines.add("  ${after[i].name} calls=${main.calls[i]} executed=${unitCounts[i]}")
    lines.add("calls:")
    for ((edge, count) in main.edges.entries.sortedWith(compareByDescending<Map.Entry<CallEdge, Int>> {
        it.value
    }.thenBy {
        after[it.key.caller].name
    }.thenBy {
        after[it.key.callee].name
    })) lines.add("  ${after[edge.caller].name} -> ${after[edge.callee].name} $count")
    lines.add("hot lines:")
    for ((line, count) in lineCounts.entries.filter {
        it.value > 0
    }.sortedWith(compareByDescending<Map.Entry<Int, Int>> {
        it.value
    }.thenBy {
        it.key
    }).take(5)) lines.add("  line $line: $count")
    val missing = lineCounts.filterValues {
        it == 0
    }.keys.sorted()
    lines.addAll(listOf("coverage: ${lineCounts.values.count { it > 0 }} of ${lineCounts.size} lines", "not executed: ${if (missing.isEmpty()) "none" else missing.joinToString(" ")}", "hot spots:"))
    for (pc in code.instructions.indices.filter {
        main.counts[it] > 0
    }.sortedWith(compareByDescending<Int> {
        main.counts[it]
    }.thenBy {
        it
    }).take(5)) lines.add("  pc=$pc count=${main.counts[pc]} ${spelling(code.instructions[pc])}")
    return lines
}
data class SourceProgram(val name: String, val lines: MutableList<Pair<Int, String>> = mutableListOf())
fun readPrograms(): Pair<List<SourceProgram>, List<String>> {
    val lines = File("input/program.src").readLines()
    val result = mutableListOf<SourceProgram>()
    for ((i, line) in lines.withIndex()) {
        if (line.startsWith("#program ")) result.add(SourceProgram(line.drop(9))) else result.last().lines.add(Pair(i + 1, line))
    }
    return Pair(result, lines)
}
fun readInput(): Map<String, List<Long>> {
    val result = mutableMapOf<String, MutableList<Long>>()
    var name = ""
    for (line in File("input/input.txt").readLines()) {
        if (line.startsWith("#input ")) {
            name = line.drop(7)
            result[name] = mutableListOf()
        } else result.getValue(name).addAll(line.split(' ').map {
            it.toLong()
        })
    }
    return result
}
fun display(position: Position, sources: List<String>): List<String> = listOf("  " + sources[position.line - 1], " ".repeat(position.column + 1) + "^")
fun write(name: String, lines: List<String>) {
    File("output").mkdirs()
    File("output/$name").writeText(if (lines.isEmpty()) "" else lines.joinToString("\n") + "\n")
}
fun main() {
    val (programs, sourceLines) = readPrograms()
    val inputs = readInput()
    val listing = mutableListOf<String>()
    val output = mutableListOf<String>()
    val diagnostics = mutableListOf<String>()
    val stats = mutableListOf<String>()
    val rows = mutableListOf(listOf("program", "status", "code", "executed", "output"))
    var compiled = 0
    val compileErrors = mutableMapOf("lexical" to 0, "syntax" to 0, "semantic" to 0)
    var runtimeErrors = 0
    var foldTotal = 0
    val ruleTotals = IntArray(7)
    var executedTotal = 0
    for (source in programs) {
        val heading = "== program ${source.name} =="
        listing.add(heading)
        output.add(heading)
        diagnostics.add(heading)
        stats.add(heading)
        val program: Program
        val semantic = Semantic()
        try {
            program = Parser(Lexer.lex(source.lines)).program()
            semantic.analyze(program)
        } catch (error: CompileError) {
            listing.add("not compiled")
            stats.add("not compiled")
            diagnostics.add("${error.kind} error ${error.position}: ${error.reason}")
            diagnostics.addAll(display(error.position, sourceLines))
            diagnostics.add("status: compile error")
            compileErrors[error.kind] = compileErrors.getValue(error.kind) + 1
            rows.add(listOf(source.name, error.kind + " error", "-", "-", "-"))
            continue
        }
        compiled++
        val reachable = reachableFrom(semantic.globals.getValue("main"), semantic.calls)
        diagnostics.addAll(warningLines(program, semantic, reachable))
        val folder = Folder()
        folder.program(program, reachable)
        foldTotal += folder.count
        val (before, area) = Codegen(semantic).generate(program, reachable)
        val after = mutableListOf<CodeUnit>()
        val rules = IntArray(7)
        for (unit in before) {
            val (code, counts) = peephole(unit.code)
            after.add(unit.copy(code = code))
            for (k in rules.indices) rules[k] += counts[k]
        }
        for (k in rules.indices) ruleTotals[k] += rules[k]
        val old = flatten(before)
        val new = flatten(after)
        val input = inputs[source.name].orEmpty()
        val main = VM.run(new.instructions, new.owners, new.starts, area, input)
        val comparison = VM.run(old.instructions, old.owners, old.starts, area, input)
        executedTotal += main.executed
        listing.addAll(listingLines(program, semantic, before, after, old, new))
        output.addAll(main.output)
        val pc = main.errorPC
        if (pc != null) {
            runtimeErrors++
            val instruction = new.instructions[pc]
            diagnostics.add("runtime error ${instruction.position}: ${main.message} in ${after[new.owners[pc]].name}")
            diagnostics.addAll(display(instruction.position, sourceLines))
            for (caller in main.callers.take(5)) diagnostics.add("  called from ${after[new.owners[caller]].name} at ${new.instructions[caller].position}")
            if (main.callers.size > 5) diagnostics.add("  ... ${main.callers.size - 5} more")
        }
        val status = if (main.message == null) "ok" else "runtime error"
        diagnostics.add("status: $status")
        stats.addAll(statsLines(old.instructions.size, after, new, main, comparison, folder.count, rules))
        rows.add(listOf(source.name, status, new.instructions.size.toString(), main.executed.toString(), main.output.size.toString()))
    }
    stats.addAll(listOf("== summary ==", "programs: ${programs.size}", "compiled: $compiled", "compile errors: lexical ${compileErrors.getValue("lexical")} syntax ${compileErrors.getValue("syntax")} semantic ${compileErrors.getValue("semantic")}", "runtime errors: $runtimeErrors", "folds: $foldTotal", "peephole: ${ruleTotals.sum()}"))
    for (i in ruleNames.indices) stats.add("  ${ruleNames[i]} ${ruleTotals[i]}")
    stats.add("executed: $executedTotal")
    val widths = (0..4).map {
        k -> rows.maxOf {
            it[k].length
        }
    }
    for (row in rows) stats.add("  " + row.mapIndexed {
        k, value -> pad(value, widths[k], k < 2)
    }.joinToString("  "))
    write("listing.txt", listing)
    write("output.txt", output)
    write("diagnostics.txt", diagnostics)
    write("stats.txt", stats)
}

enum class ToyType(val text: String) {
    INT("int"), BOOL("bool"), VOID("void");
    companion object {
        fun read(text: String): ToyType? = entries.firstOrNull {
            it.text == text
        }
    }
}
data class Name(val text: String, val position: Position)
class Variable(val type: ToyType, val name: Name, var initializer: Expr? = null, val size: Int? = null, val sizePosition: Position? = null) {
    var id = -1;
    var address = -1;
    var slot = -1
}
class Function(val type: ToyType, val name: Name, val parameters: List<Variable>, val body: Stmt) {
    var id = -1
}
sealed interface Top {
    data class VariableDecl(val variable: Variable) : Top
    data class FunctionDecl(val function: Function) : Top
}
data class Program(val declarations: List<Top>, val end: Position)
class Expr(val position: Position, var kind: ExprKind) {
    var reference: Int? = null;
    var type: ToyType? = null
}
sealed interface ExprKind {
    data class Integer(val value: Long) : ExprKind
    data class BooleanValue(val value: Boolean) : ExprKind
    data object Read : ExprKind
    data class VariableRef(val name: Name) : ExprKind
    data class Element(val name: Name, val index: Expr) : ExprKind
    data class Call(val name: Name, val arguments: List<Expr>) : ExprKind
    data class Unary(val op: String, val value: Expr) : ExprKind
    data class Binary(val op: String, val left: Expr, val right: Expr) : ExprKind
}
class Stmt(val position: Position, var kind: StmtKind) {
    var reference: Int? = null
}
sealed interface StmtKind {
    data class Block(val statements: List<Stmt>, val close: Position) : StmtKind
    data class Declaration(val variable: Variable) : StmtKind
    data class Assignment(val name: Name, val index: Expr?, val value: Expr) : StmtKind
    data class Call(val value: Expr) : StmtKind
    data class Conditional(val condition: Expr, val yes: Stmt, val no: Stmt?) : StmtKind
    data class WhileLoop(val condition: Expr, val body: Stmt) : StmtKind
    data class ForLoop(val initial: Stmt?, val condition: Expr?, val update: Stmt?, val body: Stmt) : StmtKind
    data object BreakLoop : StmtKind
    data object ContinueLoop : StmtKind
    data class ReturnValue(val value: Expr?) : StmtKind
    data class Print(val values: List<Expr>) : StmtKind
    data object Empty : StmtKind
}
class Parser(val tokens: List<Token>) {
    var index = 0
    val peek: Token get() = tokens[index]
    val text: String get() = peek.text
    fun failure(): CompileError = CompileError("syntax", peek.position, if (peek.kind == "end") "unexpected end of program" else "unexpected '$text'")
    fun take(): Token {
        val token = peek;
        if (token.kind != "end") index++;
        return token
    }
    fun expect(text: String): Token {
        if (this.text != text) throw failure();
        return take()
    }
    fun name(): Name {
        if (peek.kind != "identifier") throw failure();
        val token = take();
        return Name(token.text, token.position)
    }
    fun type(): ToyType {
        val type = ToyType.read(text) ?: throw failure();
        take();
        return type
    }
    fun program(): Program {
        val declarations = mutableListOf<Top>()
        while (peek.kind != "end") {
            val type = this.type();
            val name = name()
            if (text == "(") {
                take();
                val parameters = mutableListOf<Variable>();
                if (text != ")") {
                    while (true) {
                        val t = this.type();
                        val n = this.name();
                        parameters.add(Variable(t, n));
                        if (text != ",") break;
                        take()
                    }
                };
                expect(")");
                declarations.add(Top.FunctionDecl(Function(type, name, parameters, block())))
            } else {
                var initial: Expr? = null;
                var size: Int? = null;
                var sizePosition: Position? = null
                if (text == "[") {
                    take();
                    if (peek.kind != "integer") throw failure();
                    sizePosition = peek.position;
                    size = take().text.toInt();
                    expect("]")
                } else if (text == "=") {
                    take();
                    initial = expression()
                };
                expect(";");
                declarations.add(Top.VariableDecl(Variable(type, name, initial, size, sizePosition)))
            }
        }
        return Program(declarations, peek.position)
    }
    fun declaration(required: Boolean): Stmt {
        val position = peek.position;
        val type = this.type();
        val name = this.name();
        var initializer: Expr? = null;
        if (text == "=") {
            take();
            initializer = expression()
        } else if (required) expect("=");
        return Stmt(position, StmtKind.Declaration(Variable(type, name, initializer)))
    }
    fun block(): Stmt {
        val position = expect("{").position;
        val statements = mutableListOf<Stmt>()
        while (text != "}") {
            if (ToyType.read(text) != null) {
                val s = declaration(false);
                expect(";");
                statements.add(s)
            } else statements.add(statement())
        };
        val close = take().position;
        return Stmt(position, StmtKind.Block(statements, close))
    }
    fun statement(): Stmt {
        val position = peek.position
        return when (text) {
            "{" -> block()
            "if" -> {
                take();
                expect("(");
                val condition = expression();
                expect(")");
                val yes = statement();
                val no = if (text == "else") {
                    take();
                    statement()
                } else null;
                Stmt(position, StmtKind.Conditional(condition, yes, no))
            }
            "while" -> {
                take();
                expect("(");
                val condition = expression();
                expect(")");
                Stmt(position, StmtKind.WhileLoop(condition, statement()))
            }
            "for" -> {
                take();
                expect("(");
                val initial = if (text == ";") null else if (ToyType.read(text) != null) declaration(true) else simple();
                expect(";");
                val condition = if (text == ";") null else expression();
                expect(";");
                val update = if (text == ")") null else simple();
                expect(")");
                Stmt(position, StmtKind.ForLoop(initial, condition, update, statement()))
            }
            "break", "continue" -> {
                val keyword = take().text;
                expect(";");
                Stmt(position, if (keyword == "break") StmtKind.BreakLoop else StmtKind.ContinueLoop)
            }
            "return" -> {
                take();
                val value = if (text == ";") null else expression();
                expect(";");
                Stmt(position, StmtKind.ReturnValue(value))
            }
            "print" -> {
                take();
                expect("(");
                val values = mutableListOf(expression());
                while (text == ",") {
                    take();
                    values.add(expression())
                };
                expect(")");
                expect(";");
                Stmt(position, StmtKind.Print(values))
            }
            else -> {
                val result = simple();
                expect(";");
                result
            }
        }
    }
    fun simple(): Stmt {
        val position = peek.position
        if (text == "read") {
            take();
            expect("(");
            expect(")");
            return Stmt(position, StmtKind.Call(Expr(position, ExprKind.Read)))
        }
        val name = this.name();
        if (text == "(") return Stmt(position, StmtKind.Call(Expr(position, ExprKind.Call(name, arguments()))))
        var index: Expr? = null;
        if (text == "[") {
            take();
            index = expression();
            expect("]")
        };
        expect("=");
        return Stmt(position, StmtKind.Assignment(name, index, expression()))
    }
    fun arguments(): List<Expr> {
        expect("(");
        val values = mutableListOf<Expr>();
        if (text != ")") {
            values.add(expression());
            while (text == ",") {
                take();
                values.add(expression())
            }
        };
        expect(")");
        return values
    }
    fun priority(op: String): Int = when (op) {
        "||" -> 1;
        "&&" -> 2;
        "==", "!=" -> 3;
        "<", "<=", ">", ">=" -> 4;
        "+", "-" -> 5;
        "*", "/", "%" -> 6;
        else -> 0
    }
    fun expression(minimum: Int = 1): Expr {
        var left = unary();
        while (priority(text) >= minimum) {
            val op = take();
            val right = expression(priority(op.text) + 1);
            left = Expr(op.position, ExprKind.Binary(op.text, left, right))
        };
        return left
    }
    fun unary(): Expr {
        if (text in listOf("-", "!")) {
            val op = take();
            return Expr(op.position, ExprKind.Unary(op.text, unary()))
        };
        return primary()
    }
    fun primary(): Expr {
        val token = peek
        if (token.kind == "integer") {
            take();
            return Expr(token.position, ExprKind.Integer(token.text.toLong()))
        }
        if (text in listOf("true", "false")) {
            take();
            return Expr(token.position, ExprKind.BooleanValue(token.text == "true"))
        }
        if (text == "read") {
            take();
            expect("(");
            expect(")");
            return Expr(token.position, ExprKind.Read)
        }
        if (text == "(") {
            take();
            val value = expression();
            expect(")");
            return value
        }
        val name = this.name();
        if (text == "(") return Expr(token.position, ExprKind.Call(name, arguments()))
        if (text == "[") {
            take();
            val index = expression();
            expect("]");
            return Expr(token.position, ExprKind.Element(name, index))
        };
        return Expr(token.position, ExprKind.VariableRef(name))
    }
}

class Symbol(val name: Name, val type: ToyType, val variable: Variable?, val function: Function?, val parameter: Boolean = false) {
    val references = mutableListOf<Position>();
    var reads = 0
}
fun canComplete(statement: Stmt): Boolean = when (val s = statement.kind) {
    is StmtKind.ReturnValue -> false;
    StmtKind.BreakLoop, StmtKind.ContinueLoop -> false;
    is StmtKind.Block -> s.statements.all {
        canComplete(it)
    };
    is StmtKind.Conditional -> s.no == null || canComplete(s.yes) || canComplete(s.no);
    else -> true
}
class Semantic {
    val symbols = mutableListOf<Symbol>();
    val globals = mutableMapOf<String, Int>();
    val scopes = mutableListOf<MutableMap<String, Int>>();
    val calls = mutableMapOf<Int, MutableSet<Int>>();
    var current: Function? = null
    fun failure(position: Position, reason: String): CompileError = CompileError("semantic", position, reason)
    fun add(variable: Variable, parameter: Boolean = false): Int {
        val id = symbols.size;
        variable.id = id;
        symbols.add(Symbol(variable.name, variable.type, variable, null, parameter));
        return id
    }
    fun add(function: Function): Int {
        val id = symbols.size;
        function.id = id;
        symbols.add(Symbol(function.name, function.type, null, function));
        return id
    }
    fun forbidden(expression: Expr): List<Position> = when (val e = expression.kind) {
        is ExprKind.VariableRef -> listOf(expression.position);
        ExprKind.Read -> listOf(expression.position);
        is ExprKind.Element -> listOf(expression.position) + forbidden(e.index);
        is ExprKind.Call -> listOf(expression.position) + e.arguments.flatMap {
            forbidden(it)
        };
        is ExprKind.Unary -> forbidden(e.value);
        is ExprKind.Binary -> forbidden(e.left) + forbidden(e.right);
        else -> emptyList()
    }
    fun analyze(program: Program) {
        for (declaration in program.declarations) {
            when (declaration) {
                is Top.VariableDecl -> {
                    val variable = declaration.variable;
                    val name = variable.name
                    if (variable.size != null) {
                        if (variable.type != ToyType.INT) throw failure(name.position, "array '${name.text}' must have element type int");
                        if (variable.size == 0) throw failure(variable.sizePosition!!, "array '${name.text}' must have a positive size")
                    }
                    else if (variable.type == ToyType.VOID) throw failure(name.position, "variable '${name.text}' cannot have type void")
                    if (name.text in globals) throw failure(name.position, "redeclaration of '${name.text}'")
                    val initializer = variable.initializer
                    if (initializer != null) {
                        forbidden(initializer).minOrNull()?.let {
                            throw failure(it, "global initializer must be constant")
                        };
                        if (this.expression(initializer) != variable.type) throw failure(name.position, "type mismatch in initialization of '${name.text}'")
                    }
                    globals[name.text] = add(variable)
                }
                is Top.FunctionDecl -> {
                    val function = declaration.function
                    if (function.name.text in globals) throw failure(function.name.position, "redeclaration of '${function.name.text}'")
                    val names = mutableSetOf<String>()
                    for (parameter in function.parameters) {
                        if (parameter.type == ToyType.VOID) throw failure(parameter.name.position, "parameter '${parameter.name.text}' cannot have type void");
                        if (!names.add(parameter.name.text)) throw failure(parameter.name.position, "redeclaration of '${parameter.name.text}'")
                    }
                    globals[function.name.text] = add(function)
                }
            }
        }
        val main = globals["main"]?.let {
            symbols[it].function
        } ?: throw failure(program.end, "no main function")
        if (main.type != ToyType.VOID || main.parameters.isNotEmpty()) throw failure(main.name.position, "main must be declared as 'void main()'")
        for (declaration in program.declarations) if (declaration is Top.FunctionDecl) {
            val function = declaration.function;
            current = function;
            scopes.clear();
            scopes.add(mutableMapOf());
            calls[function.id] = mutableSetOf()
            for (parameter in function.parameters) scopes[0][parameter.name.text] = add(parameter, true)
            for (statement in (function.body.kind as StmtKind.Block).statements) this.statement(statement, 0)
            if (function.type != ToyType.VOID && canComplete(function.body)) throw failure(function.name.position, "missing return in function '${function.name.text}'")
        }
        current = null;
        scopes.clear()
    }
    fun lookup(name: Name, read: Boolean, call: Boolean = false): Int {
        val id = scopes.asReversed().firstNotNullOfOrNull {
            it[name.text]
        } ?: globals[name.text] ?: throw failure(name.position, "undeclared ${if (call) "function" else "identifier"} '${name.text}'")
        symbols[id].references.add(name.position);
        if (read) symbols[id].reads++;
        return id
    }
    fun variable(name: Name, array: Boolean, read: Boolean): Int {
        val id = lookup(name, read);
        val symbol = symbols[id]
        if (symbol.function != null) throw failure(name.position, "'${name.text}' is a function, not a variable")
        if (!array && symbol.variable!!.size != null) throw failure(name.position, "array '${name.text}' used without index")
        if (array && symbol.variable!!.size == null) throw failure(name.position, "'${name.text}' is not an array")
        return id
    }
    fun expression(expression: Expr, callStatement: Boolean = false): ToyType {
        val type = when (val e = expression.kind) {
            is ExprKind.Integer -> ToyType.INT;
            ExprKind.Read -> ToyType.INT
            is ExprKind.BooleanValue -> ToyType.BOOL
            is ExprKind.VariableRef -> {
                val id = variable(e.name, false, true);
                expression.reference = id;
                symbols[id].type
            }
            is ExprKind.Element -> {
                val id = variable(e.name, true, true);
                expression.reference = id;
                if (this.expression(e.index) != ToyType.INT) throw failure(e.name.position, "index of '${e.name.text}' must be int");
                ToyType.INT
            }
            is ExprKind.Call -> {
                val id = lookup(e.name, true, true);
                expression.reference = id
                val function = symbols[id].function ?: throw failure(e.name.position, "'${e.name.text}' is not a function")
                if (e.arguments.size != function.parameters.size) throw failure(e.name.position, "wrong number of arguments to '${e.name.text}' (expected ${function.parameters.size}, found ${e.arguments.size})")
                for ((k, argument) in e.arguments.withIndex()) if (this.expression(argument) != function.parameters[k].type) throw failure(e.name.position, "argument ${k + 1} of '${e.name.text}' must be ${function.parameters[k].type.text}")
                if (!callStatement && function.type == ToyType.VOID) throw failure(e.name.position, "void function '${e.name.text}' used as a value")
                current?.let {
                    calls.getOrPut(it.id) {
                        mutableSetOf()
                    }.add(id)
                };
                function.type
            }
            is ExprKind.Unary -> {
                val found = this.expression(e.value);
                val required = if (e.op == "-") ToyType.INT else ToyType.BOOL;
                if (found != required) throw failure(expression.position, "operator '${e.op}' requires ${required.text} operand");
                found
            }
            is ExprKind.Binary -> {
                val a = this.expression(e.left);
                val b = this.expression(e.right)
                if (e.op in listOf("+", "-", "*", "/", "%", "<", "<=", ">", ">=")) {
                    if (a != ToyType.INT || b != ToyType.INT) throw failure(expression.position, "operator '${e.op}' requires int operands");
                    if (e.op in listOf("+", "-", "*", "/", "%")) ToyType.INT else ToyType.BOOL
                }
                else if (e.op in listOf("==", "!=")) {
                    if (a != b) throw failure(expression.position, "operator '${e.op}' requires operands of the same type");
                    ToyType.BOOL
                }
                else {
                    if (a != ToyType.BOOL || b != ToyType.BOOL) throw failure(expression.position, "operator '${e.op}' requires bool operands");
                    ToyType.BOOL
                }
            }
        }
        expression.type = type;
        return type
    }
    fun statement(statement: Stmt, loops: Int) {
        when (val s = statement.kind) {
            is StmtKind.Declaration -> {
                val variable = s.variable;
                val name = variable.name
                if (variable.type == ToyType.VOID) throw failure(name.position, "variable '${name.text}' cannot have type void")
                if (name.text in scopes.last()) throw failure(name.position, "redeclaration of '${name.text}'")
                val initializer = variable.initializer;
                if (initializer != null && this.expression(initializer) != variable.type) throw failure(name.position, "type mismatch in initialization of '${name.text}'")
                scopes.last()[name.text] = add(variable)
            }
            is StmtKind.Assignment -> {
                val id = variable(s.name, s.index != null, false);
                statement.reference = id;
                if (s.index != null && this.expression(s.index) != ToyType.INT) throw failure(s.name.position, "index of '${s.name.text}' must be int");
                if (this.expression(s.value) != symbols[id].type) throw failure(s.name.position, "type mismatch in assignment to '${s.name.text}'")
            }
            is StmtKind.Call -> this.expression(s.value, true)
            is StmtKind.Conditional -> {
                if (this.expression(s.condition) != ToyType.BOOL) throw failure(statement.position, "condition of 'if' must be bool");
                this.statement(s.yes, loops);
                s.no?.let {
                    this.statement(it, loops)
                }
            }
            is StmtKind.WhileLoop -> {
                if (this.expression(s.condition) != ToyType.BOOL) throw failure(statement.position, "condition of 'while' must be bool");
                this.statement(s.body, loops + 1)
            }
            is StmtKind.ForLoop -> {
                scopes.add(mutableMapOf());
                s.initial?.let {
                    this.statement(it, loops)
                };
                if (s.condition != null && this.expression(s.condition) != ToyType.BOOL) throw failure(statement.position, "condition of 'for' must be bool");
                s.update?.let {
                    this.statement(it, loops)
                };
                this.statement(s.body, loops + 1);
                scopes.removeAt(scopes.lastIndex)
            }
            StmtKind.BreakLoop -> if (loops == 0) throw failure(statement.position, "'break' outside loop")
            StmtKind.ContinueLoop -> if (loops == 0) throw failure(statement.position, "'continue' outside loop")
            is StmtKind.ReturnValue -> {
                val function = current!!
                if (function.type == ToyType.VOID && s.value != null) throw failure(statement.position, "function '${function.name.text}' must not return a value")
                if (function.type != ToyType.VOID) {
                    val value = s.value ?: throw failure(statement.position, "function '${function.name.text}' must return a value");
                    if (this.expression(value) != function.type) throw failure(statement.position, "return value of '${function.name.text}' must be ${function.type.text}")
                }
            }
            is StmtKind.Print -> for ((k, value) in s.values.withIndex()) if (this.expression(value) != ToyType.INT) throw failure(statement.position, "argument ${k + 1} of 'print' must be int")
            is StmtKind.Block -> {
                scopes.add(mutableMapOf());
                for (value in s.statements) this.statement(value, loops);
                scopes.removeAt(scopes.lastIndex)
            }
            StmtKind.Empty -> Unit
        }
    }
}

data class CallEdge(val caller: Int, val callee: Int)
data class Frame(val locals: MutableList<Long>, val returnAddress: Int)
data class VMResult(val output: List<String>, val counts: IntArray, val calls: IntArray, val edges: Map<CallEdge, Int>, val executed: Int, val maxStack: Int, val maxDepth: Int, val errorPC: Int?, val message: String?, val callers: List<Int>)
object VM {
    fun run(code: List<Instruction>, owners: List<Int>, starts: List<Int>, area: Int, input: List<Long>): VMResult {
        val unitAt = starts.withIndex().associate {
            it.value to it.index
        };
        val global = LongArray(area);
        val stack = mutableListOf<Long>();
        val frames = mutableListOf<Frame>();
        val counts = IntArray(code.size);
        val calls = IntArray(starts.size);
        val edges = mutableMapOf<CallEdge, Int>();
        val output = mutableListOf<String>()
        var pc = 0;
        var read = 0;
        var executed = 0;
        var maxStack = 0;
        var maxDepth = 0;
        var message: String? = null;
        var errorPC: Int? = null
        fun pop(): Long = stack.removeAt(stack.lastIndex)
        execution@ while (true) {
            if (executed == 100000) {
                message = "instruction limit exceeded";
                errorPC = pc;
                break
            }
            val instruction = code[pc];
            val op = instruction.op;
            val args = instruction.operands;
            counts[pc]++;
            executed++;
            var next = pc + 1
            when (op) {
                "PUSH" -> stack.add(args[0])
                "POP" -> pop()
                "LOADG" -> stack.add(global[args[0].toInt()])
                "STOREG" -> global[args[0].toInt()] = pop()
                "LOADL" -> stack.add(frames.last().locals[args[0].toInt()])
                "STOREL" -> frames.last().locals[args[0].toInt()] = pop()
                "LOADA", "STOREA" -> {
                    val value = if (op == "STOREA") pop() else 0L;
                    val index = pop();
                    if (index < 0 || index >= args[1]) message = "index $index out of bounds for array of size ${args[1]}" else if (op == "LOADA") stack.add(global[(args[0] + index).toInt()]) else global[(args[0] + index).toInt()] = value
                }
                "ADD", "SUB", "MUL", "DIV", "MOD" -> {
                    val b = pop();
                    val a = pop();
                    if (op in listOf("DIV", "MOD") && b == 0L) message = "division by zero" else {
                        val value = when (op) {
                            "ADD" -> a + b;
                            "SUB" -> a - b;
                            "MUL" -> a * b;
                            "DIV" -> a / b;
                            else -> a - b * (a / b)
                        };
                        if (value in -2147483648L..2147483647L) stack.add(value) else message = "integer overflow"
                    }
                }
                "NEG" -> {
                    val value = -pop();
                    if (value in -2147483648L..2147483647L) stack.add(value) else message = "integer overflow"
                }
                "NOT" -> {
                    val value = pop();
                    stack.add(if (value == 0L) 1L else 0L)
                }
                "LT", "LE", "GT", "GE", "EQ", "NE" -> {
                    val b = pop();
                    val a = pop();
                    val value = when (op) {
                        "LT" -> a < b;
                        "LE" -> a <= b;
                        "GT" -> a > b;
                        "GE" -> a >= b;
                        "EQ" -> a == b;
                        else -> a != b
                    };
                    stack.add(if (value) 1L else 0L)
                }
                "JUMP" -> next = args[0].toInt()
                "JUMPF", "JUMPT" -> {
                    val value = pop();
                    if (if (op == "JUMPF") value == 0L else value != 0L) next = args[0].toInt()
                }
                "CALL" -> if (frames.size == 100) message = "call depth limit exceeded" else {
                    val n = args[1].toInt();
                    val values = stack.takeLast(n).toMutableList();
                    repeat(n) {
                        pop()
                    };
                    frames.add(Frame(values, pc + 1));
                    next = args[0].toInt();
                    val unit = unitAt.getValue(next);
                    calls[unit]++;
                    val edge = CallEdge(owners[pc], unit);
                    edges[edge] = (edges[edge] ?: 0) + 1
                }
                "ENTER" -> {
                    val locals = frames.last().locals;
                    repeat(args[0].toInt() - locals.size) {
                        locals.add(0)
                    }
                }
                "RET", "RETV" -> next = frames.removeAt(frames.lastIndex).returnAddress
                "READ" -> if (read == input.size) message = "read past end of input" else stack.add(input[read++])
                "PRINT" -> {
                    val n = args[0].toInt();
                    val values = stack.takeLast(n);
                    repeat(n) {
                        pop()
                    };
                    output.add(values.joinToString(" "))
                }
                "HALT" -> {
                    maxStack = maxOf(maxStack, stack.size);
                    maxDepth = maxOf(maxDepth, frames.size);
                    break@execution
                }
            }
            if (message != null) {
                errorPC = pc;
                break
            }
            maxStack = maxOf(maxStack, stack.size);
            maxDepth = maxOf(maxDepth, frames.size);
            pc = next
        }
        return VMResult(output, counts, calls, edges, executed, maxStack, maxDepth, errorPC, message, frames.drop(1).asReversed().map {
            it.returnAddress - 1
        })
    }
}
